function normText(s, opts){
  opts = opts || {};
  var t = String(s == null ? '' : s);
  if (opts.lower !== false) t = t.toLowerCase();
  if (opts.punct !== false) t = t.replace(/[.,!?;:'"()\[\]{}<>\/\\|`~@#$%^&*_+=\u3002\uff0c\uff01\uff1f\uff1b\uff1a\u201c\u201d\u2018\u2019\uff08\uff09\u3010\u3011]/g, ' ');
  if (opts.articles) t = t.replace(/\b(a|an|the)\b/g, ' ');
  return t.replace(/\s+/g, ' ').trim();
}

function tokenize(s, mode){
  var t = String(s == null ? '' : s);
  if (mode === 'char') return t.replace(/\s+/g, '').split('');
  var out = [], buf = '';
  for (var i = 0; i < t.length; i++){
    var c = t.charAt(i), code = t.charCodeAt(i);
    var cjk = (code >= 0x4e00 && code <= 0x9fff) || (code >= 0x3040 && code <= 0x30ff);
    if (cjk){ if (buf){ out.push(buf); buf = ''; } out.push(c); }
    else if (/\s/.test(c)){ if (buf){ out.push(buf); buf = ''; } }
    else buf += c;
  }
  if (buf) out.push(buf);
  return out;
}

function ngrams(tokens, n){
  var out = [];
  for (var i = 0; i + n <= tokens.length; i++) out.push(tokens.slice(i, i + n).join('\u0001'));
  return out;
}

function counter(arr){
  var m = {};
  for (var i = 0; i < arr.length; i++) m[arr[i]] = (m[arr[i]] || 0) + 1;
  return m;
}

function clippedOverlap(cand, ref){
  var a = counter(cand), b = counter(ref), hit = 0;
  for (var k in a) if (Object.prototype.hasOwnProperty.call(a, k)){
    var r = b[k] || 0;
    hit += a[k] < r ? a[k] : r;
  }
  return hit;
}

function bleu(candidate, reference, maxN){
  maxN = maxN || 4;
  var c = tokenize(normText(candidate)), r = tokenize(normText(reference));
  if (!c.length || !r.length) return { score: 0, precisions: [], bp: 0, candLen: c.length, refLen: r.length };
  var logSum = 0, precisions = [], usable = 0;
  for (var n = 1; n <= maxN; n++){
    var cg = ngrams(c, n), rg = ngrams(r, n);
    if (!cg.length){ precisions.push(0); continue; }
    var hit = clippedOverlap(cg, rg);
    // smoothing (add-1 on zero hits) so short outputs do not collapse to 0
    var p = hit > 0 ? hit / cg.length : 1 / (2 * cg.length);
    precisions.push(round4(hit / cg.length));
    logSum += Math.log(p); usable++;
  }
  if (!usable) return { score: 0, precisions: precisions, bp: 0, candLen: c.length, refLen: r.length };
  var bp = c.length > r.length ? 1 : Math.exp(1 - r.length / c.length);
  var score = bp * Math.exp(logSum / usable);
  return { score: round4(score), precisions: precisions, bp: round4(bp), candLen: c.length, refLen: r.length };
}

function lcsLength(a, b){
  var m = a.length, n = b.length;
  if (!m || !n) return 0;
  var prev = new Array(n + 1), cur = new Array(n + 1), i, j;
  for (j = 0; j <= n; j++) prev[j] = 0;
  for (i = 1; i <= m; i++){
    cur[0] = 0;
    for (j = 1; j <= n; j++){
      cur[j] = a[i - 1] === b[j - 1] ? prev[j - 1] + 1 : (cur[j - 1] > prev[j] ? cur[j - 1] : prev[j]);
    }
    for (j = 0; j <= n; j++) prev[j] = cur[j];
  }
  return prev[n];
}

function rougeL(candidate, reference, beta){
  beta = beta == null ? 1.2 : beta;
  var c = tokenize(normText(candidate)), r = tokenize(normText(reference));
  if (!c.length || !r.length) return { precision: 0, recall: 0, f: 0, lcs: 0 };
  var l = lcsLength(c, r);
  var p = l / c.length, rc = l / r.length;
  var f = (p + rc) === 0 ? 0 : ((1 + beta * beta) * p * rc) / (rc + beta * beta * p);
  return { precision: round4(p), recall: round4(rc), f: round4(f), lcs: l };
}

function rougeN(candidate, reference, n){
  n = n || 1;
  var cg = ngrams(tokenize(normText(candidate)), n), rg = ngrams(tokenize(normText(reference)), n);
  if (!cg.length || !rg.length) return { precision: 0, recall: 0, f: 0 };
  var hit = clippedOverlap(cg, rg);
  var p = hit / cg.length, r = hit / rg.length;
  var f = (p + r) === 0 ? 0 : 2 * p * r / (p + r);
  return { precision: round4(p), recall: round4(r), f: round4(f) };
}

function exactMatch(candidate, reference){
  return normText(candidate, { articles: true }) === normText(reference, { articles: true });
}

function tokenF1(candidate, reference){
  var c = tokenize(normText(candidate, { articles: true }));
  var r = tokenize(normText(reference, { articles: true }));
  if (!c.length || !r.length) return { precision: 0, recall: 0, f1: 0, common: 0 };
  var hit = clippedOverlap(c, r);
  if (!hit) return { precision: 0, recall: 0, f1: 0, common: 0 };
  var p = hit / c.length, rc = hit / r.length;
  return { precision: round4(p), recall: round4(rc), f1: round4(2 * p * rc / (p + rc)), common: hit };
}

function editDistance(a, b){
  a = String(a == null ? '' : a); b = String(b == null ? '' : b);
  var m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  var prev = new Array(n + 1), i, j;
  for (j = 0; j <= n; j++) prev[j] = j;
  for (i = 1; i <= m; i++){
    var cur = [i];
    for (j = 1; j <= n; j++){
      var cost = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
      var v = prev[j] + 1;
      if (cur[j - 1] + 1 < v) v = cur[j - 1] + 1;
      if (prev[j - 1] + cost < v) v = prev[j - 1] + cost;
      cur[j] = v;
    }
    prev = cur;
  }
  return prev[n];
}

function similarity(a, b){
  var la = String(a == null ? '' : a).length, lb = String(b == null ? '' : b).length;
  var max = la > lb ? la : lb;
  if (!max) return 1;
  return round4(1 - editDistance(a, b) / max);
}

function passAtK(n, c, k){
  n = Math.floor(n); c = Math.floor(c); k = Math.floor(k);
  if (!(n > 0) || k <= 0) return { value: 0, error: 'n and k must be positive' };
  if (c < 0 || c > n) return { value: 0, error: 'c must be within 0..n' };
  if (n - c < k) return { value: 1, error: null };
  var prod = 1;
  for (var i = 0; i < k; i++) prod *= (n - c - i) / (n - i);
  return { value: round4(1 - prod), error: null };
}

function round4(x){ return Math.round(x * 10000) / 10000; }

function evaluate(candidate, reference){
  var b = bleu(candidate, reference, 4);
  var rl = rougeL(candidate, reference);
  var r1 = rougeN(candidate, reference, 1);
  var r2 = rougeN(candidate, reference, 2);
  var f1 = tokenF1(candidate, reference);
  return {
    bleu: b.score, bleuDetail: b,
    rouge1: r1.f, rouge2: r2.f, rougeL: rl.f, rougeLDetail: rl,
    exactMatch: exactMatch(candidate, reference),
    f1: f1.f1, f1Detail: f1,
    editDistance: editDistance(candidate, reference),
    similarity: similarity(candidate, reference)
  };
}

function evaluateBatch(pairs){
  var rows = [], sum = { bleu: 0, rougeL: 0, f1: 0, em: 0, sim: 0 };
  for (var i = 0; i < pairs.length; i++){
    var r = evaluate(pairs[i].candidate, pairs[i].reference);
    rows.push({ index: i, bleu: r.bleu, rougeL: r.rougeL, f1: r.f1, exactMatch: r.exactMatch, similarity: r.similarity });
    sum.bleu += r.bleu; sum.rougeL += r.rougeL; sum.f1 += r.f1;
    sum.em += r.exactMatch ? 1 : 0; sum.sim += r.similarity;
  }
  var n = pairs.length || 1;
  return {
    rows: rows, count: pairs.length,
    avg: { bleu: round4(sum.bleu / n), rougeL: round4(sum.rougeL / n), f1: round4(sum.f1 / n),
           exactMatch: round4(sum.em / n), similarity: round4(sum.sim / n) }
  };
}

function parsePairs(text){
  var lines = String(text || '').split(/\r?\n/), out = [], errors = [];
  for (var i = 0; i < lines.length; i++){
    var ln = lines[i].trim();
    if (!ln) continue;
    var parts = ln.split('|');
    if (parts.length < 2){ errors.push('line ' + (i + 1) + ': expected "candidate | reference"'); continue; }
    out.push({ candidate: parts[0].trim(), reference: parts.slice(1).join('|').trim() });
  }
  return { pairs: out, errors: errors };
}
